opts = {"A": ("SRQ", "RHS"), "B": ("SRQ", "SAS"), "C": ("SQR", "SAS"), "D": ("SQR", "RHS")}
seg = lambda a, b: "".join(sorted(a + b))
equal_sides = {frozenset((seg("P", "Q"), seg("S", "R"))), frozenset((seg("Q", "R"),))}
right_angles = {("PQR", "Q"), ("SRQ", "R")}  # angle PQR at Q, angle SRQ at R

def side_eq(s1, s2):
    return s1 == s2 or frozenset((s1, s2)) in equal_sides

def holds(t2, crit):
    t1 = "PQR"
    m = dict(zip(t1, t2))
    def ang_right(t, v):
        return any(set(a) == set(t) and b == v for a, b in right_angles)
    # each vertex v of t1: its opposite/adjacent sides
    for v in t1:  # find the right-angle vertex pair
        if ang_right(t1, v) and ang_right(t2, m[v]):
            others = [u for u in t1 if u != v]
            adj = [seg(v, u) for u in others]
            adj2 = [seg(m[v], m[u]) for u in others]
            hyp, hyp2 = seg(*others), seg(m[others[0]], m[others[1]])
            if crit == "SAS":
                return all(side_eq(a, b) for a, b in zip(adj, adj2))
            if crit == "RHS":
                return side_eq(hyp, hyp2) and any(side_eq(a, b) for a, b in zip(adj, adj2))
    return False

result = True
match = [k for k, (t2, crit) in opts.items() if holds(t2, crit) == result]
assert len(match) == 1
print(f"ANSWER={match[0]}")

