ORDER = ["TL", "TR", "BR", "BL"]        # clockwise
def step(frame):
    new = {}
    for i, pos in enumerate(ORDER):
        sym, up = frame[pos]
        nxt = ORDER[(i + 1) % 4]
        new[nxt] = (sym, (not up) if nxt == "TL" else up)
    return new
