code = {"+": "sister", "-": "father", "*": "wife", "/": "mother"}
expr = [("A", "+", "B"), ("B", "-", "C"), ("C", "/", "D"), ("D", "*", "E"), ("E", "-", "F"), ("F", "/", "G")]
mother, father, wife, female = {}, {}, {}, set()
for a, op, b in expr:
    r = code[op]
    if r == "mother": mother[b] = a; female.add(a)
    elif r == "father": father[b] = a
    elif r == "wife": wife[b] = a; female.add(a)
    elif r == "sister": female.add(a)
for c, f in father.items():
    if f in wife and c not in mother:
        mother[c] = wife[f]
def relation(x, y):          # what y is to x
    kid = "Daughter" if y in female else "Son"
    if mother.get(y) == x or father.get(y) == x:
        return kid
    p = mother.get(y) or father.get(y)
    for pp in (mother.get(y), father.get(y)):
        if pp and (mother.get(pp) == x or father.get(pp) == x):
            mid = "Daughter" if pp in female else "Son"
            return f"{mid}’s {kid.lower()}"
    return None
